func buildContentTypeAncestorWhere[Q sqlite.Filterable](cols contentTypeAncestorColumns) contentTypeAncestorWhere[Q] {
	return contentTypeAncestorWhere[Q]{
		cols:          cols,
		ContentTypeID: sqlite.Where[Q, string](cols.ContentTypeID.Expression),
		AncestorID:    sqlite.Where[Q, string](cols.AncestorID.Expression),
		Depth:         sqlite.Where[Q, int64](cols.Depth.Expression),
		R:             contentTypeAncestorWhereR[Q]{cols: cols},
	}
}

// contentTypeAncestorWhereR holds the relationship-based filters of
// contentTypeAncestorWhere under the R namespace — mirroring the model's
// R struct — so they cannot collide with column-based filter fields.
type contentTypeAncestorWhereR[Q sqlite.Filterable] struct {
	cols contentTypeAncestorColumns
}

// HasAncestorContentType filters parents that have a matching AncestorContentType using a
// correlated EXISTS subquery (semi-join). Unlike an INNER JOIN it does not
// multiply parent rows, so no DISTINCT is needed. The optional filters are
// applied to the subquery (i.e. to ContentTypes).
func (w contentTypeAncestorWhereR[Q]) HasAncestorContentType(filters ...bob.Mod[*dialect.SelectQuery]) mods.Where[Q] {
	q := sqlite.Select(
		sm.Columns(sqlite.Raw("1")),
		sm.From(ContentTypes.NameExpr()),
		sm.Where(ContentTypes.Columns.ID.EQ(w.cols.AncestorID)),
	)
	q.Apply(filters...)
	return mods.Where[Q]{E: sqlite.Exists(q)}
}

// HasContentType filters parents that have a matching ContentType using a
// correlated EXISTS subquery (semi-join). Unlike an INNER JOIN it does not
// multiply parent rows, so no DISTINCT is needed. The optional filters are
// applied to the subquery (i.e. to ContentTypes).
func (w contentTypeAncestorWhereR[Q]) HasContentType(filters ...bob.Mod[*dialect.SelectQuery]) mods.Where[Q] {
	q := sqlite.Select(
		sm.Columns(sqlite.Raw("1")),
		sm.From(ContentTypes.NameExpr()),
		sm.Where(ContentTypes.Columns.ID.EQ(w.cols.ContentTypeID)),
	)
	q.Apply(filters...)
	return mods.Where[Q]{E: sqlite.Exists(q)}
}
